insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('PG', 'default', 'Papua New Guinea reference chart of accounts', '{}'::jsonb, true, 'companies', array['PG-IFRS-IS', 'PG-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in the texts read for Papua New Guinea, and no text read names a standard setter or a framework for company accounts. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-style statements below (IAS 1, expenses by nature), with the accounts a Papua New Guinea trading company keeps — GST output and input tax, import GST owed to Customs, salary and wages tax withheld, superannuation contributions and withholding taxes payable.', 'ias-1')
