    ('PG-P-IMP', 'invoice', 'tax', -100, '2125', null, null, 100, null, 30),
    ('PG-P-IMP', 'credit_note', 'base', 100, null, '8b', array['8b']::text[], -100, 'PG-GST', 10),
    ('PG-P-IMP', 'credit_note', 'tax', 100, '1150', '8', array['8']::text[], -100, 'PG-GST', 20),
