    ('PG-S-10', 'invoice', 'base', 100, null, '5a', array['5a']::text[], 100, 'PG-GST', 10),
    ('PG-S-10', 'invoice', 'tax', 100, '2100', '6', array['6']::text[], 100, 'PG-GST', 20),
    ('PG-S-10', 'credit_note', 'base', 100, null, '5a', array['5a']::text[], -100, 'PG-GST', 10),
    ('PG-S-10', 'credit_note', 'tax', 100, '2100', '6', array['6']::text[], -100, 'PG-GST', 20),
