insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('PG', 'PG-GST', 'GST return (form G1)', array['month']::declaration_period[], 'month'::declaration_period, date '2024-01-01', null, 'Form G1, Goods and Services Tax Return (Goods and Services Tax Act 2003 as amended), filed for a tax period (a month): sixteen lines in three blocks — output debits (1 to 7), input credits (8 to 12) and the summary of GST payable or refundable (13 to 16). The form is GST-inclusive on the sales side: lines 1 and 5 are totals here (exclusive base plus GST) and the exclusive figure sits in box 5a. A registered person files monthly (guide read; the form asks for a tax period month and year). Line 15 is signed: negative is the refund.', true,'day_of_month_after_period'::filing_deadline_rule, 21, null, 'IRC fact sheet on section 65A: the supplier, like all other persons registered for GST, is required to file its return by the 21st day of the following month. The payment is made with the return (form G1, line 15, remittance enclosed). A due date on a weekend or a holiday is not shifted by this rule.', 's65a-fact-sheet', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('PG', 'PG-GST', '1', 'total', 'Line 1 — Total sales and employee benefits for the tax period, GST included', '{}'::jsonb, 10, null, array['4', '5']::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 1 — total sales and employee benefits for the tax period including GST charged, exempt and zero-rated sales included (note 1). Here lines 4 and 5 added.', 'g1-form'),
  ('PG', 'PG-GST', '2', 'base', 'Line 2 — Less exempt sales', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 2 — exempt sales of the period (note 2), included in line 1.', 'g1-form'),
  ('PG', 'PG-GST', '3', 'base', 'Line 3 — Zero rated sales', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 3 — zero rated sales of the period (note 3), included in line 1.', 'g1-form'),
  ('PG', 'PG-GST', '4', 'total', 'Line 4 — Add lines 2 and 3', '{}'::jsonb, 40, null, array['2', '3']::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 4 — lines 2 and 3 added.', 'g1-form'),
  ('PG', 'PG-GST', '5', 'total', 'Line 5 — Total GST taxable sales (line 1 less line 4), GST included', '{}'::jsonb, 50, null, array['5a:base', '6:tax']::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 5 — deduct the total in line 4 from line 1. Here the exclusive base of box 5a plus the GST of box 6.', 'g1-form'),
  ('PG', 'PG-GST', '5a', 'base', 'Line 5a — GST taxable sales, GST excluded', '{}'::jsonb, 55, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Not a line of the form: the exclusive value of the taxable sales of line 5, which the engine posts and from which line 5 is rebuilt.', 'g1-form'),
  ('PG', 'PG-GST', '6', 'tax', 'Line 6 — Output debits (line 5 divided by eleven)', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 6 — divide the taxable sales of line 5 by eleven, the tax fraction of 10 %.', 'g1-form'),
  ('PG', 'PG-GST', '7', 'tax', 'Line 7 — Deferred import liabilities', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 7 — only applicable to approved entities with GST liabilities deferred on imports. Declared and empty: a decision of the preparer, no tax code posts to it.', 'g1-form'),
  ('PG', 'PG-GST', '8', 'tax', 'Line 8 — GST paid on business inputs bought during the tax period', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 8 — all the GST paid during the period when buying business inputs, capital goods and the GST paid on imports included, cars and the purchases of the exempt employee benefits left out (notes 4 and 7).', 'g1-form'),
  ('PG', 'PG-GST', '8a', 'base', 'Line 8a — Local purchases carrying creditable GST, GST excluded', '{}'::jsonb, 85, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Not a line of the form: the exclusive value of the local purchases whose GST is posted to line 8.', 'g1-form'),
  ('PG', 'PG-GST', '8b', 'base', 'Line 8b — Imports, customs value', '{}'::jsonb, 86, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Not a line of the form: the customs value of the imported goods whose GST is posted to line 8; the form asks for the GST only.', 'g1-form'),
  ('PG', 'PG-GST', '9', 'tax', 'Line 9 — Less GST paid for exempt sales', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 9 — GST paid on the inputs used for exempt sales, by the apportionment of note 5. Declared and empty: the apportionment is a decision of the preparer (see the README).', 'g1-form'),
  ('PG', 'PG-GST', '10', 'tax', 'Line 10 — GST paid for private purposes', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 10 — GST paid on goods and services bought for business and later used privately (note 6). Declared and empty: a decision of the preparer.', 'g1-form'),
  ('PG', 'PG-GST', '11', 'total', 'Line 11 — Add lines 9 and 10', '{}'::jsonb, 110, null, array['9', '10']::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 11 — lines 9 and 10 added.', 'g1-form'),
  ('PG', 'PG-GST', '12', 'total', 'Line 12 — Input credits (line 8 less line 11)', '{}'::jsonb, 120, null, array['8']::text[], array['11']::text[], null, null, false, false, null, 'Form G1, line 12 — deduct the total in line 11 from line 8; copied to line 14.', 'g1-form'),
  ('PG', 'PG-GST', '13', 'total', 'Line 13 — Output debits (lines 6 and 7)', '{}'::jsonb, 130, null, array['6', '7']::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 13 — lines 6 and 7 added.', 'g1-form'),
  ('PG', 'PG-GST', '14', 'total', 'Line 14 — Deduct input credits (from line 12)', '{}'::jsonb, 140, null, array['12']::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 14 — the input credits of line 12.', 'g1-form'),
  ('PG', 'PG-GST', '15', 'total', 'Line 15 — GST payable (positive) or refundable (negative)', '{}'::jsonb, 150, null, array['13']::text[], array['14', '16']::text[], null, null, false, false, null, 'Form G1, line 15 — GST payable, remittance enclosed, or refundable; the output debits of line 13 less the input credits of line 14 and less the section 65A credit of line 16 (fact sheet example: K1,000 output, K750 input credit, K1,000 withheld, K750 refundable). Signed: negative is the refund.', 'g1-form'),
  ('PG', 'PG-GST', '16', 'tax', 'Line 16 — GST section 65A credit allowable', '{}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form G1, line 16 and note 8 — a person subject to a section 65A withholding notice enters the total payment withheld for the month. Declared and empty: the withholding is not modelled (see the README).', 'g1-form')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

